Recipes.Recipe:
$baselineRoot = Get-BenchmarkInput BaselineRoot
$candidateRoot = Get-BenchmarkInput CandidateRoot
$manifest = Get-BenchmarkInput ManifestPath
$imageRoot = Get-BenchmarkInput ImageRoot
$outputRoot = Get-BenchmarkInput OutputRoot
$iterations = [int](Get-BenchmarkInput Iterations 12)
$warmup = [int](Get-BenchmarkInput Warmup 3)
$repoRoot = Get-BenchmarkInput RepoRoot
$expectedSource = Get-BenchmarkInput ExpectedSource
$source = (git -C $repoRoot rev-parse HEAD).Trim()
if ($source -ne $expectedSource -or (git -C $repoRoot status --porcelain)) { throw 'Candidate source is not frozen and clean' }
Add-Type -Path (Join-Path $PSScriptRoot 'VersionedCorpusSession.cs')
New-BenchmarkSuite 'paired-whole-image-decoding' -OutputRoot $outputRoot {
 Set-BenchmarkPolicy -Warmup $warmup -Iterations $iterations -Order GroupedRotated -OutlierMode None
 Add-BenchmarkMetadata ManifestSha256 (Get-FileHash -LiteralPath $manifest).Hash
 Add-BenchmarkMetadata BaselineCoreSha256 (Get-FileHash -LiteralPath (Join-Path $baselineRoot 'CodeGlyphX.dll')).Hash
 Add-BenchmarkMetadata CandidateCoreSha256 (Get-FileHash -LiteralPath (Join-Path $candidateRoot 'CodeGlyphX.dll')).Hash
 Add-BenchmarkMetadata CandidateSource $source
 Add-BenchmarkMetadata CandidateWorktreeClean 'true'
 Add-BenchmarkMetadata Scope 'Nineteen fixed complete-image requests, including a negative, formerly unsupported MaxiCode and four-QR image; separate collectible assembly contexts, identical preloaded RGBA32 and options. Reflection invocation is identical in both operations. Input loading and outcome evaluation are outside measurement.'
 Add-BenchmarkCases { Add-BenchmarkCase FixedImageCorpus @{} }
 Set-BenchmarkSetup {
  param($case,$run)
  $root=if($case.Engine -eq 'Baseline'){$baselineRoot}else{$candidateRoot}
  $run.Session=[VersionedCorpusSession]::new($root,$manifest,$imageRoot)
 }
 foreach($name in 'Baseline','Candidate') {
  Add-BenchmarkEngine $name {
   Add-BenchmarkOperation Decode { param($case,$run) $run.Session.Decode() }
  }
 }
 Add-BenchmarkValidation { param($case,$run) $run.Outcomes=$run.Session.Evaluate();if($run.Outcomes.Length -ne $run.Session.Count){throw 'Some requests were not processed'} }
 Add-BenchmarkMetric Requests { param($case,$run) $run.Session.Count }
 Add-BenchmarkMetric CorrectImages { param($case,$run) @($run.Outcomes | Where-Object Status -eq Correct).Count }
 Add-BenchmarkMetric UnexpectedImages { param($case,$run) @($run.Outcomes | Where-Object {$_.Unexpected.Length -gt 0}).Count }
 Add-BenchmarkMetric InconclusiveImages { param($case,$run) @($run.Outcomes | Where-Object Status -eq Inconclusive).Count }
 Set-BenchmarkArtifacts Json, Csv, Markdown
}

