using System;
using System.IO;
using System.Reflection;
using System.Runtime.Loader;
public sealed class VersionedCorpusSession : IDisposable {
 private sealed class Context : AssemblyLoadContext {
  private readonly string root;
  public Context(string root) : base(isCollectible:true) { this.root=root; }
  protected override Assembly Load(AssemblyName name) { var path=Path.Combine(root,name.Name+".dll");return File.Exists(path)?LoadFromAssemblyPath(path):null; }
 }
 private readonly Context context;
 private readonly object session;
 private readonly MethodInfo decode,evaluate;
 private object output;
 public int Count { get; }
 public VersionedCorpusSession(string root,string manifest,string imageRoot) {
  context=new Context(root);
  var type=context.LoadFromAssemblyPath(Path.Combine(root,"CodeGlyphX.Benchmarks.dll")).GetType("CodeGlyphX.Benchmarks.CorpusSession",true);
  session=Activator.CreateInstance(type,new object[]{manifest,imageRoot});
  decode=type.GetMethod("Decode");evaluate=type.GetMethod("Evaluate");Count=(int)type.GetProperty("Count").GetValue(session);
 }
 public void Decode() { output=decode.Invoke(session,new object[]{"CodeGlyphX",true}); }
 public Array Evaluate() { return (Array)evaluate.Invoke(session,new object[]{"CodeGlyphX",output}); }
 public void Dispose() { context.Unload(); }
}

